with src as (select * from departments where dept_name = 'Finance' and location in ('Singapore', 'London')), DepartmentsStats as (select location, case when budget >= 3594000 then 'high' when budget >= 1364000 then 'mid' else 'low' end as budget_bucket, concat_ws(', ', sort_array(collect_set(location))) as location_values from src group by location, case when budget >= 3594000 then 'high' when budget >= 1364000 then 'mid' else 'low' end) select location, budget_bucket, location_values from DepartmentsStats order by budget_bucket, location limit 10
